<?php
// File: public/index.php
// Map:
// - All pages are static HTML generated by the docs build (apps/docs → public/); Herd serves them directly.
// - Clean URLs: "/docs/colors/palettes" serves palettes.html (links have no .html, scripts/clean-urls.mjs).
// - Old "/ui/*" URLs: 301 redirect to the OmniaUI site.
// - Route "/src/scss/json/*.json" to the color JSON used by js/colors.js (palette playground).
// - Anything else: 404.

declare(strict_types=1);

$requestPath = parse_url($_SERVER["REQUEST_URI"] ?? "/", PHP_URL_PATH) ?? "/";
$normalizedPath = "/" . ltrim($requestPath, "/");

if (str_contains($normalizedPath, "..")) {
    http_response_code(400);
    echo "Bad request";
    exit;
}

$projectRoot = dirname(__DIR__);

if ($normalizedPath === "/") {
    header("Content-Type: text/html; charset=UTF-8");
    readfile(__DIR__ . "/index.html");
    exit;
}

// Clean URLs (as on the live site, see scripts/clean-urls.mjs): "/docs/colors/palettes" serves palettes.html.
$page = __DIR__ . rtrim($normalizedPath, "/") . ".html";
// "/ui/components/" (a folder without index.html next to components.html): redirect to "/ui/components", as live.
if (str_ends_with($normalizedPath, "/") && is_file($page) && !is_file(__DIR__ . $normalizedPath . "index.html")) {
    header("Location: " . rtrim($normalizedPath, "/"), true, 301);
    exit;
}
if (!str_ends_with($normalizedPath, ".html") && is_file($page)) {
    header("Content-Type: text/html; charset=UTF-8");
    readfile($page);
    exit;
}

// Components, blocks and webicons moved to the OmniaUI site (October 2026): send old /ui/... links there.
// Same base URL as OMNIAUI_URL in apps/docs/src/lib/site.mjs.
if (str_starts_with($normalizedPath, "/ui/")) {
    header("Location: https://omniaui.test" . $normalizedPath, true, 301);
    exit;
}

if (str_starts_with($normalizedPath, "/src/scss/json/")) {
    $jsonFile = $projectRoot . $normalizedPath;

    if (is_file($jsonFile)) {
        header("Content-Type: application/json; charset=UTF-8");
        readfile($jsonFile);
        exit;
    }
}

http_response_code(404);
echo "Not Found";
